const TextInput = ({value,setValue}:{value: string, setValue:any}) => {
    return (
      <input
        style={{
          backgroundColor: "transparent",
          marginBottom: 2,
          borderWidth: 0,
          borderStyle: "solid",
          borderBottomWidth:1,
          display:'flex'
        }}
        value={value}
        onChange={(e)=>setValue(e)}
      />
    );
  };

  export default TextInput;
